INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist digitale Transformation nur Technologieeinführung?', 2, '[{"text": "Nein", "correct": true, "because": "Umfasst auch Prozesse und Kultur"}, {"text": "Ja", "correct": false, "because": "Mehr als nur Technik"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit digitaler Transformation?', 3, '[{"text": "Effizienz steigern", "correct": true, "because": "Prozesse optimieren"}, {"text": "Kosten erhöhen", "correct": false, "because": "Ziel ist Senkung"}, {"text": "Manuelle Arbeit fördern", "correct": false, "because": "Automatisierung im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur digitalen Transformation?', 5, '[{"text": "Technologie", "correct": true, "because": "Grundlage"}, {"text": "Kulturanpassung", "correct": true, "because": "Mitarbeiter einbinden"}, {"text": "Hohe Preise", "correct": false, "because": "Effizienz zählt"}, {"text": "Weniger Innovation", "correct": false, "because": "Innovation ist Kern"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Digitale Transformation verändert Prozesse. b) Sie betrifft nur IT-Abteilungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Alle Bereiche betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der digitalen Transformation?', 4, '[{"text": "Kundenerwartungen", "correct": false, "because": "Treiben Wandel"}, {"text": "Technologische Trends", "correct": false, "because": "Wichtig für Strategie"}, {"text": "Bürodeko", "correct": true, "because": "Kein direkter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob digitale Transformation nur für Großunternehmen ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch KMUs profitieren"}, {"text": "Ja", "correct": false, "because": "Größe egal"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt digitale Transformation?', 3, '[{"text": "Papier zu Cloud", "correct": true, "because": "Digitalisierung von Prozessen"}, {"text": "Manuelle Eingabe", "correct": false, "because": "Kein Wandel"}, {"text": "Alte Software", "correct": false, "because": "Kein Fortschritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche profitieren von digitaler Transformation?', 5, '[{"text": "Produktion", "correct": true, "because": "Automatisierung"}, {"text": "Vertrieb", "correct": true, "because": "Online-Kanäle"}, {"text": "Papierarchivierung", "correct": false, "because": "Veraltet"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Digitale Transformation nutzt Daten. b) Sie macht alles komplizierter. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Komplexität oft reduziert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für digitale Transformation?', 4, '[{"text": "Strategie", "correct": false, "because": "Planung essenziell"}, {"text": "Technologie", "correct": false, "because": "Grundvoraussetzung"}, {"text": "Manuelle Abläufe", "correct": true, "because": "Digital ersetzt analog"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist digitale Transformation ein einmaliger Prozess?', 2, '[{"text": "Nein", "correct": true, "because": "Kontinuierliche Anpassung"}, {"text": "Ja", "correct": false, "because": "Kein Ende"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien fördern digitale Transformation?', 4, '[{"text": "Cloud", "correct": true, "because": "Flexibilität"}, {"text": "Big Data", "correct": true, "because": "Datenanalyse"}, {"text": "Papierformulare", "correct": false, "because": "Veraltet"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass digitale Transformation nur Kosten spart. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Umsatz steigern"}, {"text": "Ja", "correct": false, "because": "Mehr als Kostensenkung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der digitalen Transformation?', 3, '[{"text": "Kundenzentrierung", "correct": true, "because": "Bedürfnisse im Fokus"}, {"text": "Langsame Umsetzung", "correct": false, "because": "Schnelligkeit zählt"}, {"text": "Hohe Ausgaben", "correct": false, "because": "Effizienz im Vordergrund"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Digitale Transformation nutzt Automatisierung. b) Sie vermeidet Technologie.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Technologie ist Kern"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet digitale Transformation?', 5, '[{"text": "Schnellere Prozesse", "correct": true, "because": "Automatisierung"}, {"text": "Bessere Kundenerfahrung", "correct": true, "because": "Digitaler Service"}, {"text": "Mehr Papier", "correct": false, "because": "Digital reduziert Papier"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei digitaler Transformation unwichtig?', 3, '[{"text": "Datenintegration", "correct": false, "because": "Verknüpfung essenziell"}, {"text": "Mitarbeiterschulung", "correct": false, "because": "Akzeptanz fördern"}, {"text": "Manuelle Eingabe", "correct": true, "because": "Automatisierung im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erfordert digitale Transformation Investitionen?', 3, '[{"text": "Ja", "correct": true, "because": "Technik und Schulung nötig"}, {"text": "Nein", "correct": false, "because": "Kosten entstehen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob digitale Transformation Arbeitsplätze abbaut?', 2, '[{"text": "Nein", "correct": true, "because": "Auch neue Jobs entstehen"}, {"text": "Ja", "correct": false, "because": "Nicht nur Abbau"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für digitale Transformation zentral?', 4, '[{"text": "Datenstrategie", "correct": true, "because": "Daten nutzen"}, {"text": "Langsame Prozesse", "correct": false, "because": "Schnelligkeit zählt"}, {"text": "Manuelle Tools", "correct": false, "because": "Digital im Fokus"}]');
